    /// The walker: probes segment `index`'s movie — a failure LEAVES THE
    /// SEGMENT OUT, `leftOut`, and a segment whose output reported a failure
    /// after its stop (`outputFailure`, #181) is left out the same way
    /// WITHOUT a movie probe; either way its microphone file is then probed
    /// (`probeLeftOutMicrophone`, #181 item 2), so a voice that reads lands in
    /// the picture's slot, `position` the segments landed before it — then
    /// its microphone, appends the `RecordingSegment` and moves to the next;
    /// past the last, concludes: a failure with the first left-out
    /// segment's error when nothing landed, else a success carrying the
    /// left-out ones. Sequential and recursive rather than concurrent,
    /// because each probe's completion is on main and the order of `landed`
    /// IS the order the landing places the clips in.
    private func probeSegment(
        _ done: Session, at index: Int, landed: [RecordingSegment],
        skipped: [UnreadableSegment]
    ) {
        guard index < done.segments.count else {
            guard !landed.isEmpty else { return conclude(done, .failure(skipped[0].error)) }
            // The reason is read LIVE: an external stop whose did-finish
            // landed first writes it during the probe (`+Delegates.swift`'s
            // `.finishing` arm), after `settle` copied `done`.
            let result = RecordingResult(
                segments: landed, choice: done.choice,
                stoppedBy: session?.stoppedBy ?? done.stoppedBy, pauses: done.pauses,
                unreadable: skipped, camera: session?.camera ?? done.camera)
            return conclude(done, .success(result))
        }
        if let failure = done.segments[index].outputFailure {
            let left = Self.leftOut(done, at: index, reason: failure)
            return probeLeftOutMicrophone(done, at: index, left: left, position: landed.count) {
                [weak self] left in
                self?.probeSegment(done, at: index + 1, landed: landed, skipped: skipped + [left])
            }
        }
        MediaImporter.probe(url: done.segments[index].movieURL, mayAsk: done.mayAsk) {
            [weak self] movie in
            guard let self else { return }
            switch movie {
            case .failure(let error):
                let left = Self.leftOut(done, at: index, error)
                self.probeLeftOutMicrophone(done, at: index, left: left, position: landed.count) {
                    [weak self] left in
                    self?.probeSegment(done, at: index + 1, landed: landed, skipped: skipped + [left])
                }
            case .success(let descriptor):
                self.probeMicrophone(done, at: index, movie: descriptor) { [weak self] segment in
                    self?.probeCameraBeside(done, at: index, segment) { [weak self] segment in
                        self?.saveCursor(done, at: index, segment) { [weak self] segment in
                            self?.probeSegment(
                                done, at: index + 1, landed: landed + [segment], skipped: skipped)
                        }
                    }
                }
            }
        }
    }

    /// Segment `index`, left out for a movie that will not probe:
    /// `unreadable`'s error for it.
    private static func leftOut(_ done: Session, at index: Int, _ error: any Error)
        -> UnreadableSegment
    {
        leftOut(done, at: index, reason: unreadable(done, at: index, error))
    }

    /// Segment `index`, left out: its movie as named, the files it left on
    /// disk (movie, then microphone, then a camera's beside it — kept, never
    /// landed, CAM-9 (7) — each only if there) and `reason` — a probe's
    /// failure, or a closed segment's `outputFailure` (#181).
    private static func leftOut(_ done: Session, at index: Int, reason: RecorderError)
        -> UnreadableSegment
    {
        let segment = done.segments[index]
        let kept = [segment.movieURL.path, segment.micURL?.path, segment.camera?.url.path]
            .compactMap { $0 }
            .filter { FileManager.default.fileExists(atPath: $0) }
        return UnreadableSegment(moviePath: segment.movieURL.path, keptFiles: kept, error: reason)
    }

    /// A left-out segment's microphone file (#181 item 2, spec §11
    /// recording): probed unless there is none, its writer reported its own
    /// failure (`micFailure`) or the file is not on disk. `then` receives
    /// `left` with `position` set and, when the file read, `micDescriptor`;
    /// a probe that fails keeps it nil, the file still named in `keptFiles`.
    private func probeLeftOutMicrophone(
        _ done: Session, at index: Int, left: UnreadableSegment, position: Int,
        then: @escaping (UnreadableSegment) -> Void
    ) {
        let placed = UnreadableSegment(
            moviePath: left.moviePath, keptFiles: left.keptFiles, error: left.error,
            position: position)
        let segment = done.segments[index]
        guard let micURL = segment.micURL, segment.micFailure == nil,
            FileManager.default.fileExists(atPath: micURL.path)
        else { return then(placed) }
        MediaImporter.probe(url: micURL, mayAsk: done.mayAsk) { mic in
            guard case .success(let descriptor) = mic else { return then(placed) }
            then(
                UnreadableSegment(
                    moviePath: left.moviePath, keptFiles: left.keptFiles, error: left.error,
                    micDescriptor: descriptor, position: position))
        }
    }

    /// The microphone's half of one segment: no microphone → done; a writer
    /// that reported an error → its sentence; otherwise the file is probed,
    /// and a probe that fails says whether the microphone ever started.
    /// `then` receives the landed segment, on main.
    private func probeMicrophone(
        _ done: Session, at index: Int, movie: MediaDescriptor,
        then: @escaping (RecordingSegment) -> Void
    ) {
        let segment = done.segments[index]
        guard let micURL = segment.micURL else {
            return then(Self.result(done, at: index, movie: movie, mic: nil, problem: nil))
        }
        if let failure = segment.micFailure {
            let problem = failure + Self.fileClause(micURL, "What it wrote is at")
            return then(Self.result(done, at: index, movie: movie, mic: nil, problem: problem))
        }
        MediaImporter.probe(url: micURL, mayAsk: done.mayAsk) { mic in
            switch mic {
            case .failure(let error):
                let problem =
                    segment.micStartedAt == nil
                    ? "The microphone never started recording, so the picture was recorded "
                        + "without it." + Self.fileClause(micURL, "Its file is at")
                    : "The microphone recording could not be read: " + error.localizedDescription
                        + Self.fileClause(micURL, "The file is at")
                then(Self.result(done, at: index, movie: movie, mic: nil, problem: problem))
            case .success(let micDescriptor):
                then(Self.result(done, at: index, movie: movie, mic: micDescriptor, problem: nil))
            }
        }
    }

